                        required
                        dir="ltr"
                        className="w-full px-4 py-3 rounded-xl border border-[#E8DCC8] bg-[#FDF8F0] focus:outline-none focus:border-[#AF6B24] focus:ring-2 focus:ring-[#AF6B24]/20 transition-all text-right"
